import { z } from "zod";
export const productSchema = z.object({
    name: z.string().min(2, "Product name must be at least 2 characters"),
    description: z.string().min(10, "Description must be at least 10 characters"),
    image: z.string().url("Product image must be a valid URL").optional().default(""),
    images: z.array(z.string().url()).optional().default([]),
    price: z.preprocess((val) => parseFloat(val), z.number().positive("Price must be positive")),
    pointValue: z.preprocess((val) => parseInt(val), z.number().nonnegative("Point value must be non-negative")),
    stock: z.preprocess((val) => parseInt(val), z.number().nonnegative("Stock must be non-negative")),
    categoryId: z.string().uuid().optional().nullable(),
    subCategoryId: z.string().uuid().optional().nullable(),
    sellingDetails: z.object({
        mrpPrice: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        sellingPrice: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        discount: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        superPointPrice: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        pointOfSalePrice: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        dealerPrice: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        resellerPrice: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        productPoint: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        gst: z.string().optional().nullable(),
        sku: z.string().optional().nullable(),
        hsnCode: z.string().optional().nullable(),
        fashionFormats: z.array(z.string()).optional().default([]),
        fashionSizes: z.array(z.string()).optional().default([]),
        weightFormats: z.array(z.string()).optional().default([]),
        deliveryCharge: z.preprocess((v) => parseFloat(v || "0"), z.number()).optional(),
        returnPolicy: z.string().optional().nullable(),
        taxes: z.string().optional().nullable(),
        productDetails: z.string().optional().nullable(),
        benefits: z.string().optional().nullable(),
        features: z.string().optional().nullable(),
        leftStock: z.preprocess((v) => parseInt(v || "0"), z.number()).optional(),
        availableStates: z.array(z.string()).optional().default([]),
        productType: z.string().optional().nullable(),
    }).optional().nullable(),
});
